from gen import *
V="verb"; N="noun"; A="adjective"; AD="adverb"; P="phrase"
T(72,1,"Скарги на здоров'я","Розповісти лікареві, що болить.",
 "Fever — температура, жар, flu — грип, sneeze — чхати, ache — біль (ниючий), symptom — симптом. Приклад: I have a fever. I have the flu. I sneeze a lot. My symptoms are a cough and a fever.",
 [W("fever","/ˈfiːvə/",N,"жар, температура","I have a fever.","У мене температура."),
  W("flu","/fluː/",N,"грип","I have the flu.","У мене грип."),
  W("sneeze","/sniːz/",V,"чхати","I sneeze a lot.","Я багато чхаю."),
  W("ache","/eɪk/",N,"ниючий біль","I have an ache in my back.","У мене болить спина."),
  W("symptom","/ˈsɪmptəm/",N,"симптом","My symptoms are a cough and a fever.","Мої симптоми — кашель і температура.")],
 ("How do you celebrate?","Повторимо. Феєрверк і святкова вечеря. Що відповісти?",["We have fireworks and a big feast.","We have fireworks and big feast.","We are have fireworks feast."],"We have fireworks and a big feast."),
 [("I have a fever.","Прослухайте. Що каже людина?",["У неї температура","У неї насіпа","У неї алергія"],"Fever."),
  ("I have the flu.","Прослухайте. Що в людини?",["Грип","Застуда","Біль у горлі"],"Flu."),
  ("I sneeze a lot.","Прослухайте. Що робить людина?",["Багато чхає","Багато кашляє","Багато спить"],"Sneeze.")],
 [("I have a ___.",["fever","sneeze","symptom"],"Температура."),
  ("I have the ___.",["flu","ache","symptom"],"Грип."),
  ("I ___ a lot.",["sneeze","fever","ache"],"Чхаю.")],
 ("Що таке symptom?",["симптом","грип","температура"],"Symptom — симптом."),
 ("У мене температура.",["I","have","a","fever"],["has","flu"],"I have a fever."),
 ("У мене грип.",["I have the flu"],"I have the flu."),
 ("What's the matter?","У мене температура. Що відповісти?",["I have a fever.","I am have fever.","My fever is."],"I have a fever."))
